ALTER TABLE "Order" ADD COLUMN "promotionId" TEXT, ADD COLUMN "promotionCode" TEXT, ADD COLUMN "riderId" TEXT, ADD COLUMN "confirmedAt" TIMESTAMP(3), ADD COLUMN "preparingAt" TIMESTAMP(3), ADD COLUMN "readyAt" TIMESTAMP(3), ADD COLUMN "outForDeliveryAt" TIMESTAMP(3), ADD COLUMN "deliveredAt" TIMESTAMP(3), ADD COLUMN "cancelledAt" TIMESTAMP(3);

CREATE TABLE "Cart" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Cart_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CartItem" ("id" TEXT NOT NULL, "cartId" TEXT NOT NULL, "productId" TEXT NOT NULL, "variantId" TEXT, "quantity" INTEGER NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "CartItem_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Combo" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "slug" TEXT NOT NULL, "description" TEXT, "imageUrl" TEXT, "price" DECIMAL(12,2) NOT NULL, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Combo_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ComboItem" ("id" TEXT NOT NULL, "comboId" TEXT NOT NULL, "productId" TEXT NOT NULL, "quantity" INTEGER NOT NULL DEFAULT 1, CONSTRAINT "ComboItem_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Session" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "refreshTokenHash" TEXT NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "revokedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "userAgent" TEXT, "ipAddress" TEXT, CONSTRAINT "Session_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PromotionRedemption" ("id" TEXT NOT NULL, "promotionId" TEXT NOT NULL, "userId" TEXT NOT NULL, "orderId" TEXT NOT NULL, "discount" DECIMAL(12,2) NOT NULL, "redeemedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "PromotionRedemption_pkey" PRIMARY KEY ("id"));
CREATE TABLE "RiderAssignment" ("id" TEXT NOT NULL, "orderId" TEXT NOT NULL, "riderId" TEXT NOT NULL, "assignedBy" TEXT NOT NULL, "assignedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "acceptedAt" TIMESTAMP(3), CONSTRAINT "RiderAssignment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PaymentWebhookEvent" ("id" TEXT NOT NULL, "provider" TEXT NOT NULL, "eventId" TEXT NOT NULL, "payloadHash" TEXT NOT NULL, "receivedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "processedAt" TIMESTAMP(3), CONSTRAINT "PaymentWebhookEvent_pkey" PRIMARY KEY ("id"));

CREATE UNIQUE INDEX "Cart_userId_key" ON "Cart"("userId"); CREATE UNIQUE INDEX "CartItem_cartId_productId_variantId_key" ON "CartItem"("cartId", "productId", "variantId"); CREATE INDEX "CartItem_cartId_idx" ON "CartItem"("cartId"); CREATE UNIQUE INDEX "Combo_slug_key" ON "Combo"("slug"); CREATE UNIQUE INDEX "ComboItem_comboId_productId_key" ON "ComboItem"("comboId", "productId"); CREATE UNIQUE INDEX "Session_refreshTokenHash_key" ON "Session"("refreshTokenHash"); CREATE INDEX "Session_userId_expiresAt_idx" ON "Session"("userId", "expiresAt"); CREATE UNIQUE INDEX "PromotionRedemption_orderId_key" ON "PromotionRedemption"("orderId"); CREATE UNIQUE INDEX "PromotionRedemption_promotionId_userId_orderId_key" ON "PromotionRedemption"("promotionId", "userId", "orderId"); CREATE INDEX "PromotionRedemption_promotionId_userId_idx" ON "PromotionRedemption"("promotionId", "userId"); CREATE UNIQUE INDEX "RiderAssignment_orderId_key" ON "RiderAssignment"("orderId"); CREATE INDEX "RiderAssignment_riderId_assignedAt_idx" ON "RiderAssignment"("riderId", "assignedAt"); CREATE UNIQUE INDEX "PaymentWebhookEvent_provider_eventId_key" ON "PaymentWebhookEvent"("provider", "eventId"); CREATE INDEX "Order_riderId_status_idx" ON "Order"("riderId", "status");

ALTER TABLE "Order" ADD CONSTRAINT "Order_promotionId_fkey" FOREIGN KEY ("promotionId") REFERENCES "Promotion"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "Order" ADD CONSTRAINT "Order_riderId_fkey" FOREIGN KEY ("riderId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "Cart" ADD CONSTRAINT "Cart_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "CartItem" ADD CONSTRAINT "CartItem_cartId_fkey" FOREIGN KEY ("cartId") REFERENCES "Cart"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "CartItem" ADD CONSTRAINT "CartItem_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "CartItem" ADD CONSTRAINT "CartItem_variantId_fkey" FOREIGN KEY ("variantId") REFERENCES "ProductVariant"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "ComboItem" ADD CONSTRAINT "ComboItem_comboId_fkey" FOREIGN KEY ("comboId") REFERENCES "Combo"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "ComboItem" ADD CONSTRAINT "ComboItem_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Session" ADD CONSTRAINT "Session_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "PromotionRedemption" ADD CONSTRAINT "PromotionRedemption_promotionId_fkey" FOREIGN KEY ("promotionId") REFERENCES "Promotion"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "PromotionRedemption" ADD CONSTRAINT "PromotionRedemption_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "RiderAssignment" ADD CONSTRAINT "RiderAssignment_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "RiderAssignment" ADD CONSTRAINT "RiderAssignment_riderId_fkey" FOREIGN KEY ("riderId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
